const rows = $.Steps.Query_Findings.data || [];
$.Helpers.setVariable('raw_findings_count', rows.length);
return rows.map(function(row) {
  return {
    finding_id: row.finding_id ? String(row.finding_id).trim() : '',
    resource_id: row.resource_id ? String(row.resource_id).trim() : '',
    hostname: row.resource_name ? String(row.resource_name).trim() : '',
    environment: 'poc',
    severity: row.severity ? String(row.severity).toLowerCase().trim() : '',
    remediation_available: row.remediation_available === true || row.remediation_available === 'true',
    cve_id: row.cve_id ? String(row.cve_id).trim() : '',
    package_name: row.package_name ? String(row.package_name).trim() : '',
    installed_version: row.installed_version ? String(row.installed_version).trim() : '',
    fixed_version: row.fixed_version ? String(row.fixed_version).trim() : '',
    advisory_id: row.advisory_id ? String(row.advisory_id).trim() : '',
    finding_status: row.status ? String(row.status).toLowerCase().trim() : '',
    runtime_active: row.runtime_active === true || row.runtime_active === 'true'
  };
});

const findings = $.Steps.Build_Findings.data || [];
const severityScore = { critical: 5, high: 4, medium: 3, low: 2, info: 1 };
const scored = findings.map(function(f) {
  var score = severityScore[(f.severity || '').toLowerCase()] || 0;
  if (f.runtime_active === true) score += 2;
  if (f.fixed_version && f.fixed_version !== '') score += 1;
  return Object.assign({}, f, { priority_score: score });
});
scored.sort(function(a, b) { return b.priority_score - a.priority_score; });
return scored;

const findings = $.Steps.Prioritize_Findings.data || [];
const eligible = findings.filter(function(f) {
  return f.hostname === 'rhel09-vuln-poc-01' &&
    f.environment === 'poc' &&
    f.finding_status === 'open' &&
    f.remediation_available === true &&
    f.cve_id !== '' &&
    f.package_name !== '' &&
    f.fixed_version !== '';
});
const top = eligible.slice(0, 1);
const selectionSummary = top.length === 1
  ? 'Selected the highest-priority open finding with an available fix on the approved POC host.'
  : findings.length === 0
    ? 'Datadog security query returned zero rows.'
    : findings.map(function(f) {
        return 'host=' + (f.hostname || 'empty') +
          ', severity=' + (f.severity || 'empty') +
          ', status=' + (f.finding_status || 'empty') +
          ', remediation=' + String(f.remediation_available) +
          ', scanner_advisory=' + (f.advisory_id || 'empty') +
          ', cve_selector=' + (f.cve_id || 'empty') +
          ', package=' + (f.package_name || 'empty') +
          ', fixed=' + (f.fixed_version || 'empty');
      }).join(' | ');
$.Helpers.setVariable('eligible_findings_count', eligible.length);
$.Helpers.setVariable('total_findings_count', top.length);
$.Helpers.setVariable('has_eligible_finding', top.length === 1);
$.Helpers.setVariable('selection_summary', selectionSummary);
return top;

const selected = $.Steps.Select_Top_Findings.data || [];
const finding = selected[0];
if (!finding || typeof finding !== 'object') {
  throw new Error('Selected finding is missing or malformed');
}
const reasons = [];
const required = ['finding_id', 'resource_id', 'hostname', 'environment', 'severity', 'cve_id', 'package_name', 'installed_version', 'finding_status', 'fixed_version'];
required.forEach(function(field) {
  if (finding[field] === undefined || finding[field] === null || String(finding[field]).trim() === '') {
    reasons.push('Missing or empty field: ' + field);
  }
});
if (finding.remediation_available !== true) reasons.push('Remediation is not available');
if (reasons.length > 0) throw new Error('Finding validation failed: ' + reasons.join('; '));
return { passed: true, finding: finding };

const result = $.Steps.Validate_Finding.data;
const f = result && result.finding;
const reasons = [];
if (!result || result.passed !== true || !f) reasons.push('Finding validation did not pass');
else {
  if (f.environment !== 'poc') reasons.push('Environment must be poc');
  if (f.hostname !== 'rhel09-vuln-poc-01') reasons.push('Host is outside the approved inventory');
  if (f.finding_status !== 'open') reasons.push('Finding must still be open');
  if (f.remediation_available !== true || f.fixed_version === '') reasons.push('A fixed version must be available');
  if (!/^CVE-[0-9]{4}-[0-9]+$/i.test(f.cve_id)) reasons.push('CVE identifier format is invalid');
  if (!/^[A-Za-z0-9][A-Za-z0-9+._-]*$/.test(f.package_name)) reasons.push('Package name format is unsafe');
}
if (reasons.length > 0) throw new Error('Remediation policy blocked: ' + reasons.join('; '));
return result;

const attributes = $.Steps.Check_Already_Remediated.attributes || {};
const status = String(attributes.status || '').toLowerCase();
const finding = $.Steps.Validate_Finding.data.finding;
if (status === 'resolved' || status === 'auto_closed') {
  throw new Error('ALREADY_REMEDIATED: finding status is ' + status);
}
if (status !== 'open') throw new Error('NOT_ACTIONABLE: finding status is ' + (status || 'unknown'));
const originalFindingId = String(finding.finding_id || '');
const aapFindingId = originalFindingId.replace(/[^A-Za-z0-9+._:-]/g, function(character) {
  return '-' + character.charCodeAt(0).toString(16).padStart(2, '0') + '-';
});
if (!/^[A-Za-z0-9][A-Za-z0-9+._:-]*$/.test(aapFindingId)) {
  throw new Error('Unable to create a safe AAP finding reference');
}
return Object.assign({}, finding, { aap_finding_id: aapFindingId });

