const response = $.Steps.Launch_AAP_Job || {};
const body = response.body || {};
const httpStatus = Number(response.status || 0);
const rawId = body.id !== undefined && body.id !== null ? body.id : body.job;
const jobId = rawId !== undefined && rawId !== null ? String(rawId) : '';
const accepted = [200, 201, 202].includes(httpStatus) && jobId !== '';
$.Helpers.setVariable('job_id', jobId);
$.Helpers.setVariable('job_state', accepted ? 'running' : 'launch_failed');
$.Helpers.setVariable('raw_job_state', String(body.status || 'pending'));
$.Helpers.setVariable('failure_reason', accepted ? '' : 'AAP launch did not return an accepted HTTP status and job ID');
return { accepted: accepted, http_status: httpStatus, job_id: jobId };

const response = $.Steps.Get_AAP_Job_Status || {};
const body = response.body || {};
const expected = String($.Variables.job_id || '');
const returned = body.id !== undefined && body.id !== null ? String(body.id) : '';
const raw = String(body.status || '').toLowerCase();
const valid = Number(response.status || 0) === 200 && returned === expected;
let state = 'unexpected';
let detail = '';
if (['new', 'pending', 'waiting', 'running'].includes(raw)) state = 'running';
else if (raw === 'successful') state = 'succeeded';
else if (['failed', 'error', 'canceled', 'cancel_request'].includes(raw)) {
  state = 'failed';
  detail = 'AAP terminal state: ' + raw;
} else detail = 'Unknown AAP job status: ' + (raw || 'empty');
$.Helpers.setVariable('status_response_valid', valid);
$.Helpers.setVariable('raw_job_state', raw);
$.Helpers.setVariable('job_state', state);
if (detail) $.Helpers.setVariable('failure_reason', detail);
return { valid: valid, raw_state: raw, normalized_state: state, job_id: returned };

const currentCount = $.Variables.poll_count || 0;
const newCount = currentCount + 1;
$.Helpers.setVariable('poll_count', newCount);
return newCount;

const totalReturned = $.Steps.Validate_Operational_Health.total_returned;
const hostList = $.Steps.Validate_Operational_Health.host_list || [];

if (!totalReturned || totalReturned === 0) {
  throw new Error('Host is not reporting to Datadog: no hosts found');
}

const host = hostList[0];
if (!host || host.up !== true) {
  throw new Error('Host is down. up=' + (host ? host.up : 'undefined'));
}

return {
  hostname: host.name,
  up: host.up,
  agent_version: host.meta && host.meta.agent_version ? host.meta.agent_version : 'unknown',
  total_returned: totalReturned,
  status: 'healthy'
};

